package com.campus.registration.service; import com.campus.registration.exception.*;import com.campus.registration.model.*;import com.campus.registration.repository.*;import java.util.*; public class RegistrationEngine{final CourseRepository courses;final RegistrationRepository regs;final PrerequisiteGraph graph;public RegistrationEngine(CourseRepository c,RegistrationRepository r,PrerequisiteGraph g){courses=c;regs=r;graph=g;}public void register(String st,String code,String sec)throws Exception{Course c=courses.get(code);if(c==null)throw new IllegalArgumentException("Course not found");if(regs.registered(st,code))throw new IllegalArgumentException("Already registered");if(regs.count(code)>=c.capacity())throw new SeatFullException("No seats available for "+code);Set<String>done=new HashSet<>();for(Section s:regs.timetable(st))done.add(s.courseCode());if(!graph.satisfied(code,done))throw new PrerequisiteNotMetException("Prerequisites not met: "+c.prerequisites());Section wanted=courses.section(code,sec);if(wanted==null)throw new IllegalArgumentException("Section not found");for(Section s:regs.timetable(st))if(wanted.overlaps(s)){String m="Clash with "+s.courseCode()+" on "+s.day()+" "+s.start()+"-"+s.end();regs.logClash(st,code,m);throw new TimetableConflictException(m);}regs.save(st,code,sec);}}